#include "unity.h"
#include "xy_ccs811.h"
#include <string.h>
static xy_error_t er;static xy_error_t init_er;static xy_error_t write_er;static uint8_t result[8]={0x01,0x90,0x00,0x2a,0,0,0,0};
xy_error_t xy_i2c_device_init(xy_i2c_device_t*d,void*h,uint16_t a,uint32_t t){memset(d,0,sizeof(*d));d->base.initialized=1;d->i2c_handle=h;d->dev_addr=a;d->timeout=t;return init_er;}xy_error_t xy_i2c_device_read_reg(xy_i2c_device_t*d,uint8_t r,uint8_t*b,size_t n){TEST_ASSERT_TRUE(d->base.initialized);if(er)return er;if(r==XY_CCS811_REG_HW_ID)*b=XY_CCS811_HW_ID_VALUE;else if(r==XY_CCS811_REG_STATUS)*b=XY_CCS811_STATUS_DATA_READY;else memcpy(b,result,n);return 0;}xy_error_t xy_i2c_device_write(xy_i2c_device_t*d,const uint8_t*b,size_t n){(void)b;(void)n;TEST_ASSERT_TRUE(d->base.initialized);return write_er;}xy_error_t xy_i2c_device_write_reg(xy_i2c_device_t*d,uint8_t r,const uint8_t*b,size_t n){(void)r;(void)b;(void)n;TEST_ASSERT_TRUE(d->base.initialized);return write_er;}uint32_t xy_hal_sys_get_tick_count(void){return 77;}void setUp(void){er=0;init_er=0;write_er=0;}void tearDown(void){}
static void ok(void){xy_ccs811_t d;xy_ccs811_sample_t s;int bus;TEST_ASSERT_EQUAL_INT(0,xy_ccs811_init(&d,&bus));TEST_ASSERT_EQUAL_INT(0,xy_ccs811_read(&d,&s));TEST_ASSERT_EQUAL_UINT16(400,s.eco2_ppm);TEST_ASSERT_EQUAL_UINT16(42,s.tvoc_ppb);TEST_ASSERT_EQUAL_UINT32(77,s.timestamp);TEST_ASSERT_EQUAL_INT(0,xy_ccs811_deinit(&d));}static void fail(void){xy_ccs811_t d;xy_ccs811_sample_t s={1,2,3};int bus;TEST_ASSERT_EQUAL_INT(0,xy_ccs811_init(&d,&bus));d.sample=s;er=XY_DEVICE_TIMEOUT;TEST_ASSERT_EQUAL_INT(XY_DEVICE_TIMEOUT,xy_ccs811_read(&d,&s));TEST_ASSERT_EQUAL_UINT16(1,s.eco2_ppm);d.i2c_dev.base.initialized=0;TEST_ASSERT_EQUAL_INT(XY_DEVICE_INVALID_PARAM,xy_ccs811_read(&d,&s));}static void init_failure_clears_transport(void){xy_ccs811_t d;int bus;init_er=XY_DEVICE_TIMEOUT;TEST_ASSERT_EQUAL_INT(XY_DEVICE_TIMEOUT,xy_ccs811_init(&d,&bus));TEST_ASSERT_FALSE(d.initialized);TEST_ASSERT_FALSE(d.i2c_dev.base.initialized);TEST_ASSERT_NULL(d.i2c_dev.i2c_handle);}static void deinit_failure_preserves_ready(void){xy_ccs811_t d;int bus;TEST_ASSERT_EQUAL_INT(0,xy_ccs811_init(&d,&bus));write_er=XY_DEVICE_TIMEOUT;TEST_ASSERT_EQUAL_INT(XY_DEVICE_TIMEOUT,xy_ccs811_deinit(&d));TEST_ASSERT_TRUE(d.initialized);TEST_ASSERT_TRUE(d.i2c_dev.base.initialized);TEST_ASSERT_NOT_NULL(d.i2c_dev.i2c_handle);}int main(void){UNITY_BEGIN();RUN_TEST(ok);RUN_TEST(fail);RUN_TEST(init_failure_clears_transport);RUN_TEST(deinit_failure_preserves_ready);return UNITY_END();}
